#!/usr/bin/env bash
set -e

# export plain svgs for Qt
for f in images/icons/*.svg images/icons/*/*.svg; do
    dir="$(dirname $f)"
    dir="resources/${dir#images/}"
    mkdir -p "$dir"
    inkscape --export-plain-svg --export-filename="$dir/$(basename $f)" "$f"
done

# Application icon, the SVG sources are generated by images/app-icon/make_svgs.py
src=images/app-icon
python3 "$src/make_svgs.py"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

render() { # svg size output
    rsvg-convert -w "$2" -h "$2" -o "$3" "$1"
}

# 16-32 px use the simplified variant, larger sizes the full one
small_or() { # size svg
    if [[ $1 -le 32 ]]; then echo "$src/tom-small.svg"; else echo "$2"; fi
}

# Icon of the main window and drag & drop, bundled with the Qt resources
for s in 16 24 32 48 64 128 256; do
    render "$(small_or $s $src/tom-windows.svg)" $s "resources/icons/tom$s.png"
done

# Windows: .ico with the sizes used by Explorer, the taskbar and the start menu at all scale factors
# sizes below 256 px are stored as bitmaps, 256 px as PNG
ico=()
for s in 16 20 24 32 40 48 64; do
    render "$(small_or $s $src/tom-windows.svg)" $s "$tmp/win$s.png"
    ico+=("$tmp/win$s.png")
done
magick "${ico[@]}" "$tmp/bitmaps.ico"
render "$src/tom-windows.svg" 256 "$tmp/win256.png"
optipng -quiet -o5 "$tmp/win256.png" 2>/dev/null || true
python3 "$src/icon_pack.py" ico res/AppIcon.ico "$tmp/bitmaps.ico" "$tmp/win256.png"

# macOS: .icns with all sizes including Retina
icns=()
for s in 16 32 64 128 256 512 1024; do
    render "$src/tom-macos.svg" $s "$tmp/mac$s.png"
    icns+=("$tmp/mac$s.png")
done
python3 "$src/icon_pack.py" icns res/AppIcon.icns "${icns[@]}"

# Linux: hicolor theme icons, named after the application ID tom-ui
rm -rf res/linux && mkdir -p res/linux/scalable res/linux/symbolic
cp "$src/tom-linux.svg" res/linux/scalable/tom-ui.svg
cp "$src/tom-symbolic.svg" res/linux/symbolic/tom-ui-symbolic.svg
for s in 16 24 32 48 64 128 256 512; do
    mkdir -p "res/linux/${s}x${s}"
    render "$(small_or $s $src/tom-linux.svg)" $s "res/linux/${s}x${s}/tom-ui.png"
done

if command -v optipng >/dev/null; then
    optipng -quiet -o5 resources/icons/tom*.png res/linux/*/tom-ui.png
fi

(cd resources && rm -f resources.qrc && rcc --project -o resources.qrc )
